USE BancaVirtual2;
GO

IF NOT EXISTS (
    SELECT 1 
    FROM INFORMATION_SCHEMA.TABLES 
    WHERE TABLE_SCHEMA = 'BancaVirtual' 
      AND TABLE_NAME = 'CredencialesFirmantesCoop'
)
BEGIN
    CREATE TABLE BancaVirtual.CredencialesFirmantesCoop
    (
        Id INT IDENTITY(1,1) PRIMARY KEY,
        NombreFirmante VARCHAR(60) NOT NULL,
		Identificacion VARCHAR(13) NOT NULL,
        Usuario VARCHAR(30) NOT NULL,
        Password VARCHAR(30) NOT NULL,
        Pin VARCHAR(10) NOT NULL,
		Cargo varchar(25) NOT NULL,
        ImagenFirma VARCHAR(MAX) NOT NULL, -- Imagen en base64
        Ubicacion VARCHAR(30) NOT NULL,
        Estado CHAR(1) NOT NULL, -- 'A' = Activo, 'B' = Baja/Inactivo

        CreacionUsuario VARCHAR(20) NOT NULL,
        CreacionFecha DATETIME NOT NULL DEFAULT GETDATE(),
        ModificaUsuario VARCHAR(20) NULL,
        ModificaFecha DATETIME NULL
    );

			INSERT INTO BancaVirtual.CredencialesFirmantesCoop
			(
				NombreFirmante,
				Identificacion,
				Usuario,
				Password,
				Pin,
				Cargo,
				ImagenFirma,
				Ubicacion,
				Estado,
				CreacionUsuario,
				CreacionFecha,
				ModificaUsuario,
				ModificaFecha
			)
			VALUES
			(
				'Prueba Firmante Eclipsoft',
				'1736698561',
				'1091583',
				'RY3qn76H',
				'Javier123_',
				'Oficial de Crédito',
				'', -- ImagenFirma en base64 (aún no definida)
				'Guayaquil, Ecuador',
				'A',
				'ADMIN',
				GETDATE(),
				NULL,
				NULL
			);

END
ELSE
BEGIN
    PRINT 'La tabla BancaVirtual.CredencialesFirmantesCoop ya existe.';
END



